                                    Retry
                                </Button>
                            </Notice>
                        ) : (
                            result.data && (
                                <>
                                    <Notice title="Evidence coverage">
                                        {result.data.notice}
                                    </Notice>
                                    {result.data.data.length ? (
                                        <Card className="p-5">
                                            <ul className="audit-list">
                                                {result.data.data.map((e) => (
                                                    <li key={e.id}>
                                                        <button
                                                            onClick={() =>
                                                                setEntry(e)
                                                            }
                                                        >
                                                            <span className="audit-time">
                                                                {formatDateTime(
                                                                    e.recorded_at,
                                                                )}
                                                                <small>
                                                                    Geometry v
                                                                    {
                                                                        e.geometry_version
                                                                    }{' '}
                                                                    · revision{' '}
                                                                    {e.revision}
                                                                </small>
                                                            </span>
                                                            <span>
                                                                <strong>
                                                                    {e.category[0].toUpperCase() +
                                                                        e.category.slice(
                                                                            1,
                                                                        )}
                                                                </strong>
                                                                <p>
                                                                    {e.reason}
                                                                </p>
                                                                <small>
                                                                    {e.actor
                                                                        ?.name ??
                                                                        'Actor not recorded'}
                                                                </small>
                                                            </span>
                                                            <History
                                                                size={16}
                                                            />
                                                        </button>
                                                    </li>
                                                ))}
                                            </ul>
                                            <Pagination
                                                page={page}
                                                last={result.data.last_page}
                                                total={result.data.total}
                                                onChange={setPage}
                                            />
                                        </Card>
                                    ) : (
                                        <Empty title="No retained changes match">
                                            Earlier geometry is not
                                            reconstructed. Clear filters or
                                            choose another boundary.
                                        </Empty>
                                    )}
                                </>
                            )
                        )}
                    </div>
                    <aside className="flow-stack rounded-xl border bg-card p-5">
                        <h3 className="text-sm font-semibold">
                            Current dependencies
