                        <Button
                            variant="outline"
                            onClick={() => onEvents(selected)}
                        >
                            Original events & follow-up
                        </Button>
                        <Button
                            variant="outline"
                            onClick={() => onPeople(selected)}
                        >
                            Person / client connection
                        </Button>
                        {canManage && (
                            <Button onClick={() => onEdit(selected)}>
                                Review boundary change
