import { WizardShell, WizardStepPane } from '@/components/wizard/shell';
import {
    AlertCircle,
    Check,
    ChevronDown,
    Info,
    Search,
    ShieldCheck,
} from 'lucide-react';
import {
    cloneElement,
    type ComponentType,
    isValidElement,
    type ReactElement,
    type ReactNode,
    useEffect,
